package io.github.samlinb.openbone.io;

import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;
import io.github.samlinb.openbone.application.*;
import io.github.samlinb.openbone.core.animation.*;
import io.github.samlinb.openbone.core.math.*;
import io.github.samlinb.openbone.core.model.*;
import static io.github.samlinb.openbone.TestData.id;
import static org.junit.jupiter.api.Assertions.*;

class PhysicsParameterCodecTest {
 static final EntityId CLIP=AnimationClip.DEFAULT_ID;
 static DocumentSnapshot base(){return new DocumentSnapshot(List.of(new Bone(id(1),"root",null,Transform.IDENTITY,0),new Bone(id(2),"spring",id(1),Transform.IDENTITY,100)),List.of(),List.of()).withConstraints(List.of(new PhysicsConstraint(id(5),"spring/name~key",0,true,id(2),List.of(1.,1.,.5,.25,.25),5000,List.of(.5,100.,.95,1.,.1,.5,1.))));}
 static DocumentSnapshot key(DocumentSnapshot d,ConstraintChannel c,double time,double value){return AnimationEdits.putConstraint(d,CLIP,id(5),c,time,List.of(value));}
 static DocumentSnapshot curves(DocumentSnapshot d,Curve curve){return AnimationEdits.curves(d,CLIP,d.animation(CLIP).keys().stream().map(Keyframe::id).collect(java.util.stream.Collectors.toSet()),List.of(curve));}
 @ParameterizedTest @EnumSource(value=ConstraintChannel.class,names={"PHYSICS_INERTIA","PHYSICS_STRENGTH","PHYSICS_DAMPING","PHYSICS_MASS","PHYSICS_WIND","PHYSICS_GRAVITY","PHYSICS_MIX"}) void allSevenRuntimeGroupsRoundtripWithDeclaredCurveDomain(ConstraintChannel channel)throws Exception{
  double a=channel==ConstraintChannel.PHYSICS_MASS?1:channel==ConstraintChannel.PHYSICS_DAMPING?.9:0,b=channel==ConstraintChannel.PHYSICS_STRENGTH?120:channel==ConstraintChannel.PHYSICS_MASS?2:channel==ConstraintChannel.PHYSICS_DAMPING?.5:1;var d=key(base(),channel,0,a);d=key(d,channel,1,b);d=curves(d,channel==ConstraintChannel.PHYSICS_MIX?Curve.STEPPED:new Curve(Curve.Kind.BEZIER,.2,0,.8,1));var codec=new SkeletonJsonCodec();var bytes=codec.encode(d,Map.of(),"");var root=new com.fasterxml.jackson.databind.ObjectMapper().readTree(bytes);String field=channel.name().substring(8).toLowerCase(Locale.ROOT);assertEquals(a,root.path("animations").path(d.animations().get(0).name()).path("physics").path("spring/name~key").path(field).get(0).path("value").asDouble());var restored=codec.decode(bytes,Path.of("D:/tmp"));var c=restored.animations().get(0).constraintTracks().get(0);assertEquals(channel,c.channel());assertEquals(List.of(a),c.keys().get(0).values());assertEquals(List.of(b),c.keys().get(1).values());var left=new PhysicsPlayer();var right=new PhysicsPlayer();for(int tick=0;tick<=60;tick++){var x=left.seek(d,CLIP,tick/60.,false).bones().get(id(2)).matrix();var bone=restored.bones().stream().filter(v->v.name().equals("spring")).findFirst().orElseThrow();var y=right.seek(restored,restored.animations().get(0).id(),tick/60.,false).bones().get(bone.id()).matrix();assertEquals(x.a(),y.a(),1e-9);assertEquals(x.tx(),y.tx(),1e-9);assertEquals(x.ty(),y.ty(),1e-9);}
 }
 @Test void linearMassAndWindPlusSteppedMixActivationShareTheSamePhysicalClock()throws Exception{var d=base();d=key(d,ConstraintChannel.PHYSICS_MASS,0,1);d=key(d,ConstraintChannel.PHYSICS_MASS,1,2);d=key(d,ConstraintChannel.PHYSICS_WIND,0,0);d=key(d,ConstraintChannel.PHYSICS_WIND,1,.5);d=key(d,ConstraintChannel.PHYSICS_MIX,0,1);d=key(d,ConstraintChannel.PHYSICS_MIX,1./60,0);d=key(d,ConstraintChannel.PHYSICS_MIX,3./60,1);var mix=d.animation(CLIP).constraintTracks().stream().filter(t->t.channel()==ConstraintChannel.PHYSICS_MIX).findFirst().orElseThrow();d=AnimationEdits.curves(d,CLIP,mix.keys().stream().map(Keyframe::id).collect(java.util.stream.Collectors.toSet()),List.of(Curve.STEPPED));var candidate=d;assertDoesNotThrow(()->RuntimeRange.validate(new ProjectCodec().decode(new ProjectCodec().encode(candidate))));}
 @Test void continuousMixAndOffGridStepTransitionsAreLosslessButRefusedByRuntime()throws Exception{var d=key(base(),ConstraintChannel.PHYSICS_MIX,0,0);d=key(d,ConstraintChannel.PHYSICS_MIX,1,1);var continuous=d;assertEquals(d,new ProjectCodec().decode(new ProjectCodec().encode(d)));assertTrue(assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(continuous)).getMessage().contains("Continuous physics mix"));d=key(base(),ConstraintChannel.PHYSICS_MIX,0,0);d=key(d,ConstraintChannel.PHYSICS_MIX,.123,1);var offGrid=curves(d,Curve.STEPPED);assertTrue(assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(offGrid)).getMessage().contains("60Hz tick"));}
 @Test void setupBlendCancellationCannotPretendMassIsItsStoredDecimalValue()throws Exception{float setup=1000,value=.001f,actual=setup+(value-setup);assertEquals(.0009765625f,actual);var d=base();var p=((PhysicsConstraint)d.constraint(id(5))).withParameter(1,0).withParameter(3,1000);d=d.withConstraints(List.of(p));d=key(d,ConstraintChannel.PHYSICS_MASS,0,.001);var candidate=d;assertEquals(d,new ProjectCodec().decode(new ProjectCodec().encode(d)));assertTrue(assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(candidate)).getMessage().contains("parameters"));}
 @Test void futureActivePhysicsAncestorIsNotMistakenForStaticParentInverse(){var d=base();var root=new PhysicsConstraint(id(6),"root physics",0,true,id(1),List.of(1.,0.,0.,0.,0.),60,List.of(0.,0.,1.,1.,1.,0.,0.));var child=((PhysicsConstraint)d.constraint(id(5))).withOrder(1);d=d.withConstraints(List.of(root,child));d=AnimationEdits.putConstraint(d,CLIP,id(6),ConstraintChannel.PHYSICS_MIX,0,List.of(0.));d=AnimationEdits.putConstraint(d,CLIP,id(6),ConstraintChannel.PHYSICS_MIX,1./60,List.of(1.));var candidate=curves(d,Curve.STEPPED);assertTrue(assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(candidate)).getMessage().contains("ancestor"));}
 @Test void resetGlobalUnknownGroupAndUnknownScalarFieldsAreRejectedPrecisely()throws Exception{var codec=new SkeletonJsonCodec();var mapper=new com.fasterxml.jackson.databind.ObjectMapper();var root=mapper.readTree(codec.encode(base(),Map.of(),""));for(String field:List.of("reset","global","unknown","massInverse")){var tree=root.deepCopy();var animation=(com.fasterxml.jackson.databind.node.ObjectNode)tree.path("animations").path(base().animations().get(0).name());var physics=animation.putObject("physics");if(field.equals("global"))physics.putObject("").putArray("wind").addObject().put("value",1);else if(field.equals("massInverse"))physics.putObject("spring/name~key").putArray("mass").addObject().put("massInverse",1);else physics.putObject("spring/name~key").putArray(field).addObject().put("time",0);var error=assertThrows(ProjectFormatException.class,()->codec.decode(mapper.writeValueAsBytes(tree),Path.of("D:/tmp")));assertTrue(error.getMessage().contains(field),error.getMessage());}}
 @Test void floatBezierAuditMatchesAnIndependentBernsteinChordPoint()throws Exception{var keys=List.of(new Keyframe(id(10),0,List.of(2.),List.of(new Curve(Curve.Kind.BEZIER,.2,0,.8,1))),new Keyframe(id(11),1,List.of(6.),List.of(Curve.LINEAR)));assertEquals(2+4*.216,FloatTimelineValue.sample(keys,0,.2664f),1e-6);assertNull(FloatTimelineValue.sample(List.of(keys.get(1)),0,.5f));assertEquals(6,FloatTimelineValue.sample(keys,0,2));}
}
